      SUBROUTINE AGENDA(LOC)CC     A MARKER HAS BEEN ENCOUNTEREDC     RUN THROUGH LIST OF UPDATES, CONSTRAINTS, AND PRINT STATEMENTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM31B.CIN'CC     LOCAL VARIABLESC      INTEGER  LOCCC-----------------------------------------------------------C     TRANSFER FROM MARKER TO LISTC      IF (LOC .EQ. 2) GO TO 50      IF (NMARKB .EQ. 0) GO TO 100      NMARK = NUM      NUM = NMARKB - 1      NDIFM = NDIF      NDIF = 1      MKG = .TRUE.      GO TO 100CC     TRANSFER BACK TO MARKERC   50 NUM = NMARK      NDIF = NDIFM      MKG = .FALSE.C  100 RETURN      END